  PRIMARY KEY (`id_item`),
  KEY `fk_item_venda` (`id_venda`),
  CONSTRAINT `fk_item_venda` FOREIGN KEY (`id_venda`) REFERENCES `venda` (`id_venda`)
) ENGINE=InnoDB AUTO_INCREMENT=5166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
