  `id_movimentacao` int NOT NULL AUTO_INCREMENT,
  `id_estoque` int NOT NULL,
  `id_franquia` int NOT NULL,
  `id_funcionario` int NOT NULL,
  `tipo_movimentacao` enum('entrada','saida') COLLATE utf8mb4_general_ci NOT NULL,
